import { Container, Grid, Typography, Card, CardContent } from "@mui/material";
import "./Skill.css";
import React from "react";

export default function Skill() {
  const skills = {
    "Programming Languages": [
      {
        name: "PHP",
        icon: (
          <svg className="icon icon-php">
            <use xlinkHref="#icon-php"></use>
          </svg>
        ),
      },
      {
        name: "Java",
        icon: (
          <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "JavaScript",
        icon: (
          <svg className="icon icon-javascript">
            <use xlinkHref="#icon-javascript"></use>
          </svg>
        ),
      },
      {
        name: "Python",
        icon: (
          <svg className="icon icon-php">
            <use xlinkHref="#icon-python"></use>
          </svg>
        ),
      },
      {
        name: "C++",
        icon: (
          <svg className="icon icon-php">
            <use xlinkHref="#icon-c"></use>
          </svg>
        ),
      },
    ],
    Frameworks: [
      {
        name: "React",
        icon: (
          <svg className="icon icon-react">
            <use xlinkHref="#icon-react"></use>
          </svg>
        ),
      },
      {
        name: "Node.js",
        icon: (
          <svg className="icon icon-nodejs">
            <use xlinkHref="#icon-nodejs"></use>
          </svg>
        ),
      },
      {
        name: "Express",
        icon: (
          <svg className="icon icon-express">
            <use xlinkHref="#icon-express"></use>
          </svg>
        ),
      },
    ],
  };
  const nameArray = ["Programming Languages", "Frameworks"];

  return (
    <div>
      <Container
        id={"skill"}
        style={{
          paddingTop: "2rem",
          paddingBottom: "2rem",
          marginBottom: "2rem",
          borderRadius: "10px",
        }}
      >
        <Typography
          variant="h2"
          sx={{
            fontWeight: "bold",
            fontSize: "3rem",
            color: "text",
            marginBottom: "1rem",
            textAlign: "center",
          }}
        >
          Skills
        </Typography>
        <Grid justify="center " container spacing={4}>
          {nameArray.map((name, index) => (
            //   <div key={index}>
                <Grid item key={index}>
                <Card
                    sx={{
                    width: 250,
                    marginTop: "1rem",
                    marginBottom: "1rem",
                    marginLeft: "auto",
                    marginRight: "auto",
                    boxShadow: "0px 0px 10px 0px rgba(0,0,0,0.2)",
                    borderRadius: "10px",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    alignItems: "center",
                    padding: "1rem",
                    }}
                >
                    <CardContent>
                    <Typography
                        variant="h5"
                        sx={{
                        fontWeight: "bold",
                        fontSize: "1.5rem",
                        color: "text",
                        marginBottom: "1.5rem",
                        textAlign: "left",
                        }}
                    >
                        {nameArray[index] || name}
                    </Typography>
                    <Typography
                        variant="body2"
                        align="left"
                        component="div"
                        sx={{
                        fontSize: "1.5rem",
                        color: "text",
                        marginBottom: "1rem",
                        }}
                    >
                        {skills[nameArray[index]].map((skill) => (
                        <div>
                            <Grid container spacing={3}>
                            <Grid item>
                                <Typography
                                variant="h5"
                                align="left"
                                component="div"
                                >
                                {skill.icon}
                                </Typography>
                            </Grid>
                            <Grid item>
                                <Typography
                                variant="h6"
                                align="left"
                                component="div"
                                >
                                {skill.name}
                                </Typography>
                            </Grid>
                            </Grid>
                        </div>
                        ))}
                    </Typography>
                    </CardContent>
                </Card>
                </Grid>
            // </div>
          ))}
        </Grid>
      </Container>
    </div>
  );
}
